        for (int v = 1; v <= 6; v++) {
            int top = opp[i][v];
            int mx = 0;
            for (int j = 0; j < 6; j++) {
                if (faces[j] != v && faces[j] != top) {
                    if (faces[j] > mx) mx = faces[j];
                }
            }
            max_side[i][v] = mx;
        }
    }
    int ans = 0;
    for (int start = 1; start <= 6; start++) {
        int cur = start;
        int sum = 0;
        for (int i = 0; i < N; i++) {
            sum += max_side[i][cur];
            cur = opp[i][cur];
        }
        if (sum > ans) ans = sum;
    }
    printf("%d\n", ans);
    return 0;
}
